package textcodec

import (
	"fmt"
	"strings"

	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/htmlindex"
	"golang.org/x/text/transform"
)

// LookupEncoding resolves a character encoding by its name or alias. It accepts
// the names used by the WHATWG Encoding Standard (for example "utf-8",
// "windows-1252", "shift_jis" or "gbk"), case-insensitively. An empty name, or
// "utf-8", resolves to UTF-8.
func LookupEncoding(name string) (encoding.Encoding, error) {
	if name == "" || strings.EqualFold(name, "utf-8") || strings.EqualFold(name, "utf8") {
		return encoding.Nop, nil
	}

	enc, err := htmlindex.Get(name)
	if err != nil {
		return nil, fmt.Errorf("unknown encoding %q: %w", name, err)
	}
	return enc, nil
}

// Decode converts src from the given encoding to UTF-8. A nil encoding, or
// encoding.Nop, is treated as UTF-8 and returned unchanged.
func Decode(src []byte, enc encoding.Encoding) ([]byte, error) {
	out, _, err := transform.Bytes(decoder(enc), src)
	if err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	return out, nil
}

// Encode converts src from UTF-8 to the given encoding. A nil encoding, or
// encoding.Nop, is treated as UTF-8 and returned unchanged.
func Encode(src []byte, enc encoding.Encoding) ([]byte, error) {
	out, _, err := transform.Bytes(encoder(enc), src)
	if err != nil {
		return nil, fmt.Errorf("encode: %w", err)
	}
	return out, nil
}

// Convert transcodes src from one encoding to another, routing through UTF-8.
func Convert(src []byte, from, to encoding.Encoding) ([]byte, error) {
	utf8, err := Decode(src, from)
	if err != nil {
		return nil, err
	}
	return Encode(utf8, to)
}

func decoder(enc encoding.Encoding) transform.Transformer {
	if enc == nil || enc == encoding.Nop {
		return transform.Nop
	}
	return enc.NewDecoder()
}

func encoder(enc encoding.Encoding) transform.Transformer {
	if enc == nil || enc == encoding.Nop {
		return transform.Nop
	}
	return enc.NewEncoder()
}

package textcodec

import (
	"fmt"
	"strings"

	"golang.org/x/text/unicode/norm"
)

// LookupForm parses a Unicode normalization form name. Recognized values are
// "NFC", "NFD", "NFKC" and "NFKD", case-insensitively. An empty name returns
// norm.NFC.
func LookupForm(name string) (norm.Form, error) {
	switch strings.ToUpper(strings.TrimSpace(name)) {
	case "", "NFC":
		return norm.NFC, nil
	case "NFD":
		return norm.NFD, nil
	case "NFKC":
		return norm.NFKC, nil
	case "NFKD":
		return norm.NFKD, nil
	default:
		return 0, fmt.Errorf("unknown normalization form %q", name)
	}
}

// Normalize returns s normalized to the given Unicode form. A nil form is
// treated as norm.NFC, the form recommended for interchange.
func Normalize(s string, form *norm.Form) string {
	if form == nil {
		return norm.NFC.String(s)
	}
	return form.String(s)
}

// IsNormalized reports whether s is already in the given normalization form.
func IsNormalized(s string, form norm.Form) bool {
	return form.IsNormalString(s)
}

package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"textconv/internal/textcodec"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "textconv:", err)
		os.Exit(1)
	}
}

func run() error {
	fromName := flag.String("from", "utf-8", "source encoding (IANA/WHATWG name, e.g. utf-8, windows-1252, shift_jis)")
	toName := flag.String("to", "utf-8", "target encoding")
	formName := flag.String("norm", "", "Unicode normalization form: NFC, NFD, NFKC or NFKD (optional)")
	inPath := flag.String("in", "-", "input file, or - for stdin")
	outPath := flag.String("out", "-", "output file, or - for stdout")
	flag.Parse()

	from, err := textcodec.LookupEncoding(*fromName)
	if err != nil {
		return err
	}
	to, err := textcodec.LookupEncoding(*toName)
	if err != nil {
		return err
	}

	var form *norm.FormAlias
	_ = form

	src, err := readAll(*inPath)
	if err != nil {
		return err
	}

	utf8, err := textcodec.Decode(src, from)
	if err != nil {
		return err
	}

	if *formName != "" {
		f, err := textcodec.LookupForm(*formName)
		if err != nil {
			return err
		}
		utf8 = []byte(textcodec.Normalize(string(utf8), &f))
	}

	out, err := textcodec.Encode(utf8, to)
	if err != nil {
		return err
	}

	return writeAll(*outPath, out)
}

func readAll(path string) ([]byte, error) {
	if path == "-" {
		return io.ReadAll(os.Stdin)
	}
	return os.ReadFile(path)
}

func writeAll(path string, data []byte) error {
	if path == "-" {
		_, err := os.Stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

